'logistic-harvest a P(1-P/K) - h P^1.5 e^{ct}': (lambda p: p[0]*P*(1-P/p[1])-p[2]*P**1.5*np.exp(p[3]*t)+p[4], [1,5,1,0.03,0]),
'P(a+bt+cP)(1-P/K) style': (lambda p: (p[0]+p[1]*t+p[4]*t*t)*P*(1-P/p[2])-p[3]*P**1.5, [0.5,0.05,5,0.5,0.0]),
'Richards: a P - b P^(1+c)': (lambda p: p[0]*P - p[1]*P**p[2]*np.exp(p[3]*t)+p[4]*P**2, [1,1,1.5,0.03,0.1]),
'sin-mod': (lambda p: p[0]*P+p[1]*P**2+p[2]*P**1.5*np.cos(p[3]*t+p[4])+p[5], [1,-0.5,-2,0.5,0,0]),
}
